; loop128: 128 bytes from HL with OUTI and JP NZ, 29 T-states a byte: safe
; while the paper is drawn (chapter 20)
loop128: ld c, VDP_DATA
        ld b, 128
.byte:  outi                    ; 18
        jp nz, .byte            ; 11
        ret
        INCLUDE "picture.inc"
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
